package scan

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"path/filepath"
	"time"

	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/internal/module"
	"github.com/mellifera/mellifera/internal/plugin"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/pkg/sdk"
	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
)

// Deps are the collaborators Run orchestrates: the storage layer, the module
// registry (resolves a library's scanner capability binding from its config),
// the plugin manager (dispenses the typed sdk.Scanner client for a binding), the
// enrich collaborators (the serial seam, retained for sync/test — B6), and the
// async-enqueue hook Notify. Scan no longer drives the metadata_source chain
// inline between Identify and PutItem (AC-async): it persists each item "pending"
// with the base §3.1 document, then — once the stream has drained — calls
// Notify(ctx, libraryID) so the enrich queue (re)derives the library's pending
// work and drains it on its worker pool. Enrich/Notify are exported fields, not
// symbols; the composition root (cmd/mellifera) constructs enrich.Deps and wires
// queue.Notify into Notify.
type Deps struct {
	Store   *store.Store
	Plugins *plugin.Manager
	Modules *module.Registry
	Enrich  enrich.Deps
	// Notify is the async-enqueue hook runScan calls once after it has persisted
	// a library's items (post-drain). cmd/mellifera wires enrich.Queue.Notify
	// here; an in-package test injects a fake. Nil is safe: runScan skips the
	// call, so the seam degrades gracefully when unwired (no panic).
	Notify func(ctx context.Context, libraryID int64)
}

// Result is the outcome of one scan: how many files the scanner emitted, how
// many items reached the store, any soft per-file warnings, and the time bounds
// of the run. api serializes it into the scan response on success.
type Result struct {
	LibraryID  int64
	Discovered int
	Persisted  int
	Warnings   []string
	StartedAt  time.Time
	FinishedAt time.Time
}

// Run orchestrates one scan of a library: GetLibrary → resolve the module →
// resolve the scanner capability → stream DiscoveredFiles → Identify each →
// assemble the base §3.1 document → PutItem (upsert by file_id) at status
// "pending" → after the stream drains, Notify(ctx, libraryID) so the enrich
// queue derives the library's pending work and drains it async. It is the ONLY
// function the api scan handler calls (pure-delegation rule, INV1). Enrichment
// is NOT awaited here (AC-async): scan returns once items are persisted pending.
//
// Hard failures (return an error, partial Result): the library, module, or
// scanner cannot be resolved, the scanner stream cannot be opened, or the
// context is cancelled. Soft failures (recorded in Result.Warnings, scan
// continues): malformed scanner options, a scanner per-file warning (e.g. an
// ffprobe soft-fail), an Identify error, or a PutItem error — AC-6 philosophy:
// one bad file never aborts the library.
func Run(ctx context.Context, deps Deps, libraryID int64) (Result, error) {
	return runScan(ctx, deps.Store, deps.Modules, deps.Plugins.Scanner,
		prodEnricher(deps.Enrich), notifier(deps.Notify), libraryID)
}

// scannerResolver obtains the typed scanner client for a module's capability
// binding. Run supplies the production resolver (plugin.Manager.Scanner); the
// in-package test injects one returning a fake sdk.Scanner (R8 — the scanner
// interface's second implementation). It is an unexported test seam and does
// not count toward the package's exported-symbol budget.
type scannerResolver func(pluginID, capabilityID string) (sdk.Scanner, error)

// enricher runs the metadata_source chain for one item, mirroring scannerResolver
// as the enrich analog (seam S6). Run supplies the production closure
// (prodEnricher over deps.Enrich); the in-package test injects a fake returning
// canned documents/status/warnings without a real subprocess (R8). It is an
// unexported test seam and does not count toward the package's exported-symbol
// budget.
type enricher func(ctx context.Context, mod module.Module, doc map[string]any, base *scannerv1.IdentifyResult) (map[string]any, string, enrich.Result, error)

// prodEnricher returns the production enrich closure over deps.Enrich — the
// enrich analog of *plugin.Manager.Scanner (the production scannerResolver).
func prodEnricher(d enrich.Deps) enricher {
	return func(ctx context.Context, mod module.Module, doc map[string]any, base *scannerv1.IdentifyResult) (map[string]any, string, enrich.Result, error) {
		return enrich.Enrich(ctx, d, mod, doc, base)
	}
}

// notifier is the async-enqueue seam: runScan calls it once after it has drained
// the scanner stream and persisted the library's items, so the enrich queue
// (re)derives their pending (item, plugin) work. It is the Notify analog of the
// enricher seam (S5). Run supplies the production notifier (deps.Notify, wired
// to enrich.Queue.Notify by cmd/mellifera); the in-package test injects a fake
// that records the call. Unexported test seam; it does not count toward the
// package's exported-symbol budget.
type notifier func(ctx context.Context, libraryID int64)

// runScan is the orchestrator body, factored out so the test can inject a fake
// scanner resolver, a fake enricher (the retained serial seam, B6), and a fake
// notifier (the async-enqueue seam, S5). Run is the verbatim contracts.md §7
// entrypoint. enrichItem is the retained serial-path seam — scan no longer
// invokes it from persist (enrichment is async via notify); it stays wired so
// the serial path remains available and tests can assert it is NOT called
// inline. (It is named enrichItem, not enrich, so the enrich package stays
// addressable for the gate resolution below.) A clean
// drain — the precondition for the sweep and the notify — is a CONFIRMED clean
// completion (the scanner stream reported nil) plus a live context; anything
// less is a warning and neither sweep nor notify runs.
func runScan(ctx context.Context, st *store.Store, mods *module.Registry, resolve scannerResolver, enrichItem enricher, notify notifier, libraryID int64) (Result, error) {
	res := Result{LibraryID: libraryID, StartedAt: time.Now().UTC()}

	lib, err := st.GetLibrary(ctx, libraryID)
	if err != nil {
		return finish(res), fmt.Errorf("scan: library %d: %w", libraryID, err)
	}
	mod, err := mods.Get(lib.ModuleID)
	if err != nil {
		return finish(res), fmt.Errorf("scan: module %q: %w", lib.ModuleID, err)
	}
	// Gate prefs are read ONCE per run (plugin-title-enrichment D5: the same
	// batched read derivation uses — module scope + this library) and resolved
	// onto the LOCAL module copy before any enricher invocation, so the
	// production-dead serial seam (prodEnricher) can never re-write a dormant
	// source's namespace if it ever fires. A read error leaves prefs empty
	// (soft, AC-6: everything inherits the config — the queue's derivation
	// behaves the same); ResolveGates returns binding copies, so the
	// registry's backing slice is never mutated.
	prefs, err := st.ListMetadataSourcePrefs(ctx, mod.ID, []int64{libraryID})
	if err != nil {
		res.Warnings = append(res.Warnings, fmt.Sprintf("scan: source gate prefs: %v", err))
		prefs = nil
	}
	mod.MetadataSources = enrich.ResolveGates(mod, prefs, libraryID)
	sc, err := resolve(mod.Scanner.PluginID, mod.Scanner.CapabilityID)
	if err != nil {
		return finish(res), fmt.Errorf("scan: scanner %s/%s: %w", mod.Scanner.PluginID, mod.Scanner.CapabilityID, err)
	}

	req, optsWarn := buildScanRequest(lib.RootPath, mod.MediaType, mod.Scanner.Options)
	if optsWarn != "" {
		res.Warnings = append(res.Warnings, optsWarn)
	}

	ss, err := sc.Scan(ctx, req)
	if err != nil {
		return finish(res), fmt.Errorf("scan: open stream: %w", err)
	}

	// Drain at store-write speed (INV4, R9). The select on ctx.Done() lets a
	// cancelled context abort even while blocked waiting for the next file
	// (B6); the scanner subprocess observes the same ctx and closes up cleanly.
	// notify and the series sweep fire ONLY after a provably clean drain — a
	// CONFIRMED clean completion (the stream reported nil) plus a live context.
	// A closed Files channel alone proves nothing: a cancelled context returns
	// the context error, and a stream that ended before completing (a
	// mid-stream error, or a bare close carrying no terminal confirmation)
	// records a warning and returns WITHOUT sweeping or notifying (the B7
	// analog: a half-drained scan never signals the queue). The series sweep
	// runs in that confirmed-clean branch and NOWHERE else: a scan whose stream
	// did not drain cleanly must never advance a series row it never observed
	// to "deleted" (serials-library box 1.6).
	observed := make(map[string]bool)
	for {
		select {
		case <-ctx.Done():
			return finish(res), ctx.Err()
		case f, ok := <-ss.Files:
			if !ok {
				// The gate is positive: a sweep needs a confirmed completion
				// AND a live context. The ctx check also closes the select
				// race where a cancel-closed channel and ctx.Done() are both
				// ready — both arms then return the context error.
				if cerr := ctx.Err(); cerr != nil {
					return finish(res), cerr
				}
				if terr := ss.Err(); terr != nil {
					res.Warnings = append(res.Warnings, fmt.Sprintf("scan: stream ended before completing: %v", terr))
					return finish(res), nil
				}
				// Provably clean drain: sweep the library's series rows that
				// this pass did not re-observe to "deleted" (vanished/renamed
				// serial directories), then hand off to the queue.
				if serr := sweepSeries(ctx, st, libraryID, observed, &res); serr != nil {
					return finish(res), serr
				}
				// Non-blocking handoff to the enrich queue (AC-async / S5).
				// The queue feeds its own bounded channel; notify does not
				// await the async drain.
				if notify != nil {
					notify(ctx, libraryID)
				}
				return finish(res), nil
			}
			res.Discovered++
			res.Warnings = append(res.Warnings, f.GetWarnings()...)
			if perr := persist(ctx, st, sc, f, mod, lib.RootPath, libraryID, observed, &res); perr != nil {
				return finish(res), perr
			}
		}
	}
}

// scanStatusDeleted is the lifecycle value the post-drain series sweep writes
// for a series row that was NOT re-observed this pass (a vanished or renamed
// serial directory). Like scanStatusPending/scanStatusStale it is owned by
// internal/enrich (INV-status-owner); scan emits the literal it needs rather
// than importing enrich's unexported consts.
const scanStatusDeleted = "deleted"

// sweepSeries advances every series row of the library that this scan pass did
// not re-observe to "deleted" (serials-library box 1.5): the directory vanished,
// or was renamed/moved (which is a NEW ser_ identity — the old row is deleted,
// and no metadata is copied across identities). Already-deleted rows are left
// untouched so repeated clean re-scans do not churn their updated_at. Errors
// are soft (AC-6): a failed row sweep is a warning and the sweep continues; a
// cancelled context aborts. The caller runs this ONLY after a provably clean
// drain: a CONFIRMED clean completion (the scanner stream reported nil) plus a
// live context.
func sweepSeries(ctx context.Context, st *store.Store, libraryID int64, observed map[string]bool, res *Result) error {
	rows, err := st.QuerySeries(ctx, libraryID, "")
	if err != nil {
		return fmt.Errorf("scan: series sweep: %w", err)
	}
	for _, sr := range rows {
		if observed[sr.RelativePath] || sr.Status == scanStatusDeleted {
			continue
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		sr.Status = scanStatusDeleted
		if err := st.PutSeries(ctx, sr); err != nil {
			res.Warnings = append(res.Warnings, fmt.Sprintf("series sweep %q: %v", sr.RelativePath, err))
			continue
		}
	}
	return nil
}

// persist identifies one discovered file and routes it by the serial-record
// marker fact (serials-library boxes 1.3/1.4): facts carrying
// `serial_record: true` assemble a serial-level base document (design.md
// §Interfaces §4 — parsed marker facts, ffprobe) and persist via PutSeries in
// the SAME drain loop as PutItem; every other file is an episode item, whose
// parsed (already carrying series_relative_path + sidecars when the scanner
// stamps them — §Interfaces §2) flows through assembleBaseDoc verbatim.
// Enrichment is NO LONGER driven inline (B1/AC-async): scan persists the base
// document — carrying parsed + ffprobe so the worker reconstructs the per-item
// base WITHOUT a re-probe (D-Q2 / S7, INV-persist-base) — and hands the library
// to the queue via runScan's post-drain notify. The retained serial enricher
// seam (B6) is not invoked here. A re-scan whose base identity changed
// advances the record to "stale" (AC-states(c)); an unchanged re-scan preserves
// the prior status so a settled record is not regressed. Identify/persist
// failures are soft (AC-6); a cancelled context is returned as an error so
// runScan stops draining (B6) and takes precedence over any concurrent soft
// failure. A parsed-unchanged re-scan additionally carries the prior
// document's derived namespaces forward (two-tier, D-11 — packaging state keys
// on the parsed+ffprobe base, so a drifted ffprobe drops `streams` alone); a
// parsed change drops them all (the changed identity invalidates every
// derived namespace).
func persist(ctx context.Context, st *store.Store, sc sdk.Scanner, f *scannerv1.DiscoveredFile, mod module.Module, rootPath string, libraryID int64, observed map[string]bool, res *Result) error {
	identified, err := sc.Identify(ctx, &scannerv1.IdentifyRequest{File: f, ModuleType: mod.MediaType})
	if err != nil {
		res.Warnings = append(res.Warnings, fmt.Sprintf("identify %q: %v", f.GetRelativePath(), err))
		return ctx.Err()
	}
	parsed := identifyParsed(identified)
	if isSerialRecord(parsed) {
		return persistSeries(ctx, st, f, parsed, mod, rootPath, libraryID, observed, res)
	}
	base := assembleBaseDoc(f, identified, mod.MediaType, mod.SchemaVersion, rootPath)
	status, carry := nextScanState(ctx, st, libraryID, f.GetFileId(), base, res)
	for k, v := range carry {
		base[k] = v // carry-forward: derived namespaces survive the document-replacing upsert
	}
	if err := st.PutItem(ctx, newItem(f, mod, libraryID, marshalDoc(base), status)); err != nil {
		res.Warnings = append(res.Warnings, fmt.Sprintf("persist %q: %v", f.GetRelativePath(), err))
		return ctx.Err()
	}
	res.Persisted++
	return nil
}

// persistSeries assembles the serial-level base document and upserts it via
// PutSeries at the marker-decided status, recording the series'
// series_relative_path in the pass's observed set (the post-drain sweep's
// re-observation basis). The series identity is (library_id,
// series_relative_path) — NOT the record's file_id — per design.md
// §Interfaces §5. Failures are soft (AC-6) like the item path.
func persistSeries(ctx context.Context, st *store.Store, f *scannerv1.DiscoveredFile, parsed map[string]any, mod module.Module, rootPath string, libraryID int64, observed map[string]bool, res *Result) error {
	rel := seriesRelativePath(parsed, f.GetRelativePath())
	doc := assembleSeriesDoc(f, parsed, rootPath)
	status, carry := nextSeriesState(ctx, st, libraryID, rel, doc, res)
	for k, v := range carry {
		doc[k] = v // carry-forward: derived namespaces survive the document-replacing upsert
	}
	if err := st.PutSeries(ctx, store.Series{
		ModuleID:      mod.ID,
		LibraryID:     libraryID,
		RelativePath:  rel,
		Document:      marshalDoc(doc),
		SchemaVersion: mod.SchemaVersion,
		Status:        status,
	}); err != nil {
		res.Warnings = append(res.Warnings, fmt.Sprintf("persist series %q: %v", rel, err))
		return ctx.Err()
	}
	observed[rel] = true
	res.Persisted++
	return nil
}

// identifyParsed projects an IdentifyResult's parsed Struct into a plain map
// (the drain-side fact view the marker routing and series assembly read). A
// nil or unmarshalable parsed yields an empty map — fact routing then treats
// the record as a plain item, the pre-serials behavior.
func identifyParsed(id *scannerv1.IdentifyResult) map[string]any {
	m := map[string]any{}
	if p := id.GetParsed(); p != nil {
		if b, err := json.Marshal(p); err == nil {
			_ = json.Unmarshal(b, &m)
		}
	}
	return m
}

// isSerialRecord reports whether the parsed facts carry the serial-record
// marker (design.md §Interfaces §1: `serial_record: true`). It keys ONLY on
// the marker fact name — never on a media-type literal (INV2: the core stays
// media-type-agnostic; a tv/image item's parsed simply never carries it).
func isSerialRecord(parsed map[string]any) bool {
	v, ok := parsed["serial_record"].(bool)
	return ok && v
}

// seriesRelativePath reads the `series_relative_path` identity fact from the
// marker facts, falling back to the record's own relative path when the fact
// is absent or not a string (a malformed marker degrades to the record's path
// — a warning-worthy identity, never a panic).
func seriesRelativePath(parsed map[string]any, fallback string) string {
	if v, ok := parsed["series_relative_path"].(string); ok && v != "" {
		return v
	}
	return fallback
}

// assembleSeriesDoc builds the serial-level base document per design.md
// §Interfaces §4: parsed (the serial-record marker facts, plus the same
// absolute_path stamp items get) and ffprobe — the verbatim FfprobeJson when
// the scanner carried one (a file-backed record's probe), an empty object
// otherwise (directory-backed). The core-managed namespaces (sources /
// _provenance / _view / _stages) populate only as metadata plugins enrich the
// document. The key set is exactly {parsed, ffprobe}: identity/lifecycle live
// in the series row's columns, not duplicated into the opaque document — but
// the derived state is no longer lost on a re-scan: persistSeries merges the
// prior document's carry (nextSeriesState) onto this fresh base.
func assembleSeriesDoc(f *scannerv1.DiscoveredFile, parsed map[string]any, rootPath string) map[string]any {
	parsedBytes, err := json.Marshal(parsed)
	if err != nil {
		parsedBytes = json.RawMessage(`{}`)
	}
	return map[string]any{
		"parsed": parsedWithAbsolutePath(json.RawMessage(parsedBytes), rootPath, f.GetRelativePath()),
		"ffprobe": func() json.RawMessage {
			if raw := f.GetFfprobeJson(); len(raw) > 0 {
				return json.RawMessage(raw) // verbatim (INV3)
			}
			return json.RawMessage(`{}`)
		}(),
	}
}

// nextSeriesState decides the lifecycle status scan persists for one serial
// record AND which derived namespaces survive the re-scan — the series mirror
// of nextScanState over the same two-tier basis: "pending" for a first sight
// (or an unreadable prior), "stale" when the parsed serial identity changed
// (AC-states(c)), and the prior status preserved for any parsed-unchanged
// re-scan — including the `deleted → ready` self-heal of a re-observed
// tombstone (fix-truncated-scan-sweep D3: a truncated pass no longer sweeps,
// and a healthy re-scan lifts the tombstones a historical truncated pass
// wrote). A "deleted" row the pass does not re-observe keeps "deleted"
// (sweepSeries's existing skip — no updated_at churn). Every parsed-unchanged
// leg carries the prior derived namespaces forward verbatim via derivedCarry
// with dropStreams=false: a series record is never packaged, so tier B's
// streams drop does not apply — ffprobe drift alone keeps both the status and
// the carry. A lookup error is soft (AC-6): it falls back to "pending" — the
// queue re-derives either way.
func nextSeriesState(ctx context.Context, st *store.Store, libraryID int64, rel string, refreshed map[string]any, res *Result) (string, map[string]any) {
	prior, err := st.GetSeriesByPath(ctx, libraryID, rel)
	if err != nil {
		return scanStatusPending, nil // first sight (or unreadable prior) -> re-queue
	}
	if parsedChanged(prior.Document, refreshed) {
		return scanStatusStale, nil // parsed identity changed: every derived namespace is invalid
	}
	// Parsed unchanged: preserve the prior status — a re-observed tombstone
	// self-heals to ready — and carry the derived namespaces forward.
	status := prior.Status
	if status == scanStatusDeleted {
		status = scanStatusReady // re-observed tombstone: self-heal (fix-truncated-scan-sweep D3)
	}
	return status, derivedCarry(prior.Document, refreshed, false)
}

// scanStatusPending/scanStatusStale/scanStatusReady are the lifecycle values
// scan writes for a persisted item or series. They are owned by internal/enrich
// (state.go INV-status-owner); scan emits the literals it needs rather than
// importing enrich's unexported consts (exporting them would breach the enrich
// <=8 exported-symbol budget). The async worker/queue consume these verbatim;
// scan produces "ready" ONLY as the nextSeriesState self-heal of a re-observed
// "deleted" row, and never produces the remaining lifecycle values
// (failed/parsed/enriched) post-B1.
const (
	scanStatusPending = "pending"
	scanStatusStale   = "stale"
	scanStatusReady   = "ready"
)

// nextScanState decides the lifecycle status scan persists for one file AND
// which derived namespaces survive the re-scan (two-tier unchanged test):
// "pending" for a first scan (no prior row) or an unreadable prior; "stale" for
// a re-scan whose parsed identity changed (AC-states(c)); and the prior status
// preserved for any parsed-unchanged re-scan (so a settled/ready item is not
// regressed back to pending). The comparison runs in two tiers over the prior
// document vs the refreshed base: tier A keys on parsed alone (parsedSignature)
// and carries every prior derived namespace forward verbatim (derivedCarry);
// tier B — parsed equal but ffprobe drifted (baseChanged) — carries the same
// namespaces MINUS `streams`, because packaging state and artifact pointers key
// on parsed+ffprobe and the changed media invalidates any packaged artifact.
// The prior document is loaded exactly once here. A GetItem error is soft
// (AC-6): it falls back to "pending" — the queue re-derives either way, and a
// transient read failure must never abort the scan.
func nextScanState(ctx context.Context, st *store.Store, libraryID int64, fileID string, refreshed map[string]any, res *Result) (string, map[string]any) {
	prior, err := st.GetItem(ctx, itemID(libraryID, fileID))
	if err != nil {
		return scanStatusPending, nil // no prior row (first scan) or unreadable -> re-queue
	}
	if parsedChanged(prior.Document, refreshed) {
		return scanStatusStale, nil // parsed identity changed: every derived namespace is invalid
	}
	// Parsed unchanged: preserve the prior status, carry the derived namespaces
	// minus `streams` when the ffprobe base also drifted (tier B).
	return prior.Status, derivedCarry(prior.Document, refreshed, baseChanged(prior.Document, refreshed))
}

// parsedSignature projects a document down to its parsed identity — the tier A
// basis for the status + enrichment-carry comparison. It is deliberately
// narrower than baseSignature: ffprobe blobs drift with scanner toolchain noise
// that leaves the parsed identity untouched, and such drift must not drop
// enrichment or regress a settled status. An absent parsed encodes as nil, so a
// field vanishing across a re-scan counts as a change.
func parsedSignature(doc map[string]any) map[string]any {
	return map[string]any{"parsed": doc["parsed"]}
}

// parsedChanged is the tier A comparison: it reports whether the parsed
// identity of a re-scan differs from the previously-persisted document — the
// same canonicalJSON byte-compare as baseChanged, keyed on parsed alone
// (parsedSignature). An unparseable prior document counts as changed, matching
// baseChanged's best-effort rule.
func parsedChanged(priorRaw json.RawMessage, refreshed map[string]any) bool {
	var prior map[string]any
	if len(priorRaw) > 0 {
		_ = json.Unmarshal(priorRaw, &prior) // best-effort; unparseable -> nil map -> treated as changed
	}
	return !bytes.Equal(
		canonicalJSON(parsedSignature(refreshed)),
		canonicalJSON(parsedSignature(prior)),
	)
}

// derivedCarry returns the prior document's derived namespaces — every key
// EXCEPT the reserved base set {parsed, ffprobe}, plus `streams` when
// dropStreams (tier B) — for the caller to merge onto the freshly assembled
// base. The reserved keys are never carried, so the new scan's facts are the
// new truth (a stale anchor must never mask a real identity change). The
// subtraction is key-set-driven, not an enumerated namespace list: any future
// derived namespace survives a re-scan without a code change. An unreadable
// prior document yields nil (nothing to carry). refreshed is the same basis
// both tiers compared; it is not consulted here — the fresh base wins by merge
// order at the call site.
func derivedCarry(priorRaw json.RawMessage, refreshed map[string]any, dropStreams bool) map[string]any {
	var prior map[string]any
	if len(priorRaw) == 0 || json.Unmarshal(priorRaw, &prior) != nil || prior == nil {
		return nil
	}
	reserved := map[string]bool{"parsed": true, "ffprobe": true}
	if dropStreams {
		reserved["streams"] = true
	}
	carry := make(map[string]any, len(prior))
	for k, v := range prior {
		if !reserved[k] {
			carry[k] = v
		}
	}
	return carry
}

// baseChanged is the tier B comparison (packaged-playback D-11, byte-identical
// to what shipped there): it reports whether the identity-bearing base fields
// (parsed + ffprobe) of a re-scan differ from the previously-persisted
// document — the basis for dropping `streams`, since packaging state keys on
// parsed+ffprobe. file_id/module_type/schema_version are stable for a re-scan
// of the same file in the same module, so they are excluded (including them
// would only re-detect "same file, same module"). Both sides are normalized
// via canonicalJSON so comparison is byte-stable regardless of JSON key order
// (a scanner/plugin may emit parsed/ffprobe keys in any order; Go sorts map
// keys on marshal).
func baseChanged(priorRaw json.RawMessage, refreshed map[string]any) bool {
	var prior map[string]any
	if len(priorRaw) > 0 {
		_ = json.Unmarshal(priorRaw, &prior) // best-effort; unparseable -> nil map -> treated as changed
	}
	return !bytes.Equal(
		canonicalJSON(baseSignature(refreshed)),
		canonicalJSON(baseSignature(prior)),
	)
}

// baseSignature projects a document down to its identity-bearing base fields
// (parsed + ffprobe) for the tier B comparison. A field absent from the source
// is encoded as nil, so a field vanishing across a re-scan counts as a change.
func baseSignature(doc map[string]any) map[string]any {
	return map[string]any{
		"parsed":  doc["parsed"],
		"ffprobe": doc["ffprobe"],
	}
}

// canonicalJSON returns a key-sorted JSON encoding of v: it marshals v, then
// round-trips the bytes through unmarshal+marshal so every nested object's keys
// land in Go's sorted order. This makes byte comparison independent of the
// source's key order (a scanner may emit ffprobe keys unordered), which the
// stale-on-rescan basis requires. A marshal/unmarshal failure yields the best
// single-pass bytes (never panics).
func canonicalJSON(v any) json.RawMessage {
	b, err := json.Marshal(v)
	if err != nil {
		return nil
	}
	var dec any
	if json.Unmarshal(b, &dec) != nil {
		return b
	}
	if out, err := json.Marshal(dec); err == nil {
		return out
	}
	return b
}

// newItem builds the store.Item for one (file, document, status) tuple: struct
// conversion at the package boundary (contracts.md §3). The scan-minted id is a
// deterministic composite of (library, file_id) — see itemID.
func newItem(f *scannerv1.DiscoveredFile, mod module.Module, libraryID int64, document json.RawMessage, status string) store.Item {
	return store.Item{
		ID:            itemID(libraryID, f.GetFileId()),
		ModuleID:      mod.ID,
		LibraryID:     libraryID,
		FileID:        f.GetFileId(),
		RelativePath:  f.GetRelativePath(),
		MediaType:     mod.MediaType,
		Document:      document,
		SchemaVersion: mod.SchemaVersion,
		Status:        status,
	}
}

// itemID mints a stable, globally-unique item id from (libraryID, file_id). It
// is deterministic so an idempotent re-scan maps a file back to the same item
// (PutItem upserts by file_id and preserves id on conflict). A real ULID is the
// long-term intent (contracts.md §4), but no ULID library is in the task's
// allowed_imports, so a deterministic composite serves the MVP.
func itemID(libraryID int64, fileID string) string {
	return fmt.Sprintf("itm_%d_%s", libraryID, fileID)
}

// buildScanRequest constructs the scanner RPC request, forwarding the module's
// scanner options verbatim. options is a json.RawMessage from the module config;
// ScanRequest.Options is a *structpb.Struct. structpb is deliberately NOT
// imported (it is outside the task's allowed_imports): the options are wrapped
// under the ScanRequest "options" key and unmarshaled, so the generated
// structpb.UnmarshalJSON builds the *structpb.Struct without this package naming
// that type. Malformed options yield a warning (soft); the scan proceeds with a
// nil Options and the scanner's module_type still guides parsing.
func buildScanRequest(libraryPath, moduleType string, options json.RawMessage) (*scannerv1.ScanRequest, string) {
	req := &scannerv1.ScanRequest{LibraryPath: libraryPath, ModuleType: moduleType}
	if len(options) == 0 {
		return req, ""
	}
	var tmp scannerv1.ScanRequest
	if err := json.Unmarshal([]byte(`{"options":`+string(options)+`}`), &tmp); err != nil {
		return req, fmt.Sprintf("scanner options: %v", err)
	}
	req.Options = tmp.Options
	return req, ""
}

// assembleBaseDoc builds the base architecture §3.1 document for one discovered
// file as a mutable map, so enrich can extend it with sources/_provenance/
// _view/_stages. A freshly scanned item carries only the raw ffprobe blob
// (verbatim bytes), the filename-parsed fields (lossless), and the core-managed
// identity fields — the per-source namespaces and computed view populate only as
// metadata plugins enrich it (§3.1 "Simple by default"). Precision is preserved:
// nothing is averaged or collapsed. The parsed Struct is read via its generated
// json marshaler (no structpb import); ffprobe bytes are embedded verbatim.
//
// rootPath is the resolved library root (store.Library.RootPath): when non-empty,
// parsed gains absolute_path = filepath.Join(rootPath, rel) for EVERY item (D-6)
// — the ONLY channel through which the image-enricher can open the file (the B1
// chain passes an empty Merge document and reconstructs the base from doc["parsed"]
// only, chain.go:115-122). Generic and media-type-agnostic (INV2): tv-parser
// ignores the new key; existing parsed keys are preserved. The stamp is
// deterministic for (rootPath, rel), so baseChanged (stale-on-rescan) is unaffected.
//
// created_at / updated_at are intentionally NOT duplicated into the opaque
// document: the store maintains them as authoritative columns (items.created_at
// is preserved across re-scans by the PutItem upsert), and a document copy could
// neither stay in sync nor preserve created_at on a re-scan.
func assembleBaseDoc(f *scannerv1.DiscoveredFile, id *scannerv1.IdentifyResult, moduleType string, schemaVersion int, rootPath string) map[string]any {
	doc := map[string]any{
		"file_id":        f.GetFileId(),
		"module_type":    moduleType,
		"schema_version": schemaVersion,
	}
	var parsedBytes json.RawMessage
	if p := id.GetParsed(); p != nil {
		if b, err := json.Marshal(p); err == nil {
			parsedBytes = json.RawMessage(b)
		}
	}
	doc["parsed"] = parsedWithAbsolutePath(parsedBytes, rootPath, f.GetRelativePath())
	if raw := f.GetFfprobeJson(); len(raw) > 0 {
		doc["ffprobe"] = json.RawMessage(raw) // verbatim (INV3)
	}
	return doc
}

// parsedWithAbsolutePath returns the parsed JSON document (the base-scanner base
// fields) carrying the additional absolute_path key when rootPath is non-empty.
// It best-effort unmarshals the incoming parsed bytes ({} on failure, matching the
// prior behavior) and re-marshals after stamping. Re-marshal sorts keys (as the
// prior direct json.Marshal of the Struct did), so the result is byte-stable for a
// given (parsed, rootPath, rel). Factored out so assembleBaseDoc stays focused.
func parsedWithAbsolutePath(parsedBytes json.RawMessage, rootPath, rel string) json.RawMessage {
	m := map[string]any{}
	if len(parsedBytes) > 0 {
		_ = json.Unmarshal(parsedBytes, &m) // best-effort; {} on failure (existing behavior)
	}
	if rootPath != "" {
		m["absolute_path"] = filepath.Join(rootPath, rel)
	}
	b, _ := json.Marshal(m)
	return json.RawMessage(b)
}

// marshalDoc serializes the (possibly enriched) document map back to the opaque
// json.RawMessage the store persists. A map of strings + json.RawMessage never
// fails to marshal; the fallback keeps a minimal valid document rather than nil.
func marshalDoc(doc map[string]any) json.RawMessage {
	if b, err := json.Marshal(doc); err == nil {
		return b
	}
	return json.RawMessage(`{}`)
}

// finish stamps the run's end time. It takes res by value (the caller's res with
// warnings already appended) and returns a completed Result.
func finish(res Result) Result {
	res.FinishedAt = time.Now().UTC()
	return res
}
